using System;using System.Collections.Generic;using System.IO;using System.Reflection;using System.Runtime.Serialization.Json;using BepInEx;using BepInEx.Configuration;using HarmonyLib;using HutongGames.PlayMaker;using UnityEngine;
[BepInPlugin("weaponspack.local.equipchecks","Local Equip Checks","1.0.0")]
public sealed class EquipChecks:BaseUnityPlugin {
 const BindingFlags All=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 string host;Type plugin,transition;object owner;int checks;readonly List<string> failures=new List<string>();readonly List<GameObject> owned=new List<GameObject>();
 object Get(object target,string name){return (target as Type??target.GetType()).GetField(name,All).GetValue(target is Type?null:target);}void Set(object target,string name,object value){(target as Type??target.GetType()).GetField(name,All).SetValue(target is Type?null:target,value);}object Call(object target,string name,params object[] args){return (target as Type??target.GetType()).GetMethod(name,All).Invoke(target is Type?null:target,args);}
 GameObject Make(string name,Transform parent=null){var go=new GameObject(name);owned.Add(go);if(parent!=null)go.transform.SetParent(parent,false);return go;}
 void Check(bool ok,string message){checks++;Logger.LogInfo((ok?"PASS: ":"FAIL: ")+message);if(!ok)failures.Add(message);}
 void Awake(){host=Path.GetFullPath(Path.Combine(Path.GetDirectoryName(Info.Location),"../../.."));try{Run();}catch(Exception error){failures.Add(error.ToString());Logger.LogError(error);}foreach(var go in owned)if(go!=null)DestroyImmediate(go);File.WriteAllText(Path.Combine(host,"result.txt"),(failures.Count==0?"PASS: ":"FAIL: ")+checks+" native equip checks; failures="+failures.Count+"\n"+string.Join("\n",failures.ToArray()));Application.Quit();}
 void Run(){var path=Path.Combine(host,"lib/ChainsawPrototype.dll");var pack=Assembly.LoadFrom(path);plugin=pack.GetType("ChainsawPrototype.Plugin",true);var inactive=Make("InactiveEquipPack");inactive.SetActive(false);owner=inactive.AddComponent(plugin);Set(plugin,"instance",owner);Set(owner,"harmony",new Harmony("weaponspack.fixture.equip"));var info=((BaseUnityPlugin)owner).Info;info.GetType().GetProperty("Location",All).SetValue(info,path,null);
  var install=plugin.GetMethod("InstallWeaponEquipCompatibility",All);Check(install!=null,"pack owns optional equip animation compatibility");if(install==null)return;
  Call(owner,"InstallWeaponEquipCompatibility");Check(!(bool)Get(owner,"packEquipInstalled"),"missing optional mod is a quiet no-op");
  var view=Make("PlayerCamera");view.AddComponent<Camera>().enabled=false;view.transform.SetPositionAndRotation(new Vector3(25,3,-17),Quaternion.Euler(5,32,-3));var arm=Make("WeaponsArm",view.transform);var parent=Make("Parent",arm.transform);parent.transform.localPosition=new Vector3(.08f,-.12f,.07f);parent.transform.localRotation=Quaternion.Euler(2,4,-1);
  var rig=Make("Chainsaw.HeldRig",view.transform);var model=Make("Chainsaw.HeldModel",view.transform);model.AddComponent<MeshRenderer>();Set(owner,"camera",view.transform);Set(owner,"weapon",rig.transform);Set(owner,"preview",model);Set(owner,"enabledPreview",true);Set(owner,"stockRead",true);Set(owner,"stockMotionReady",true);Set(owner,"stockMotion",Quaternion.identity);Set(owner,"stockShift",Vector3.zero);
  var placement=Read(plugin.GetNestedType("StockPlacement",All),Path.Combine(host,"lib/ChainsawPlacement.json"));Set(owner,"stockPlacement",placement);BuildBones(rig.transform,(Array)Get(placement,"bones"));Call(owner,"ApplyStockPlacement");var bones=(Array)Get(owner,"stockBones");var basePoints=new Vector3[bones.Length];for(int i=0;i<bones.Length;i++)basePoints[i]=((Transform)bones.GetValue(i).GetType().GetProperty("Key").GetValue(bones.GetValue(i),null)).position;
  Vector3 baseModel=model.transform.position;Quaternion baseTurn=model.transform.rotation;Call(owner,"ApplyStockPlacement");Check(Vector3.Distance(baseModel,model.transform.position)<.00001f,"standalone saved pose is unchanged without WW");
  string wild=Path.Combine(host,"lib/WildWasteland.dll");if(!File.Exists(wild)){Check(!(bool)Get(owner,"packEquipInstalled"),"standalone stays independent after repeated pose use");return;}
  var ww=Assembly.LoadFrom(wild);transition=ww.GetType("WildWasteland.Modules.Guns.WeaponTransition",true);var guns=ww.GetType("WildWasteland.Modules.Guns.GunsModule",true);var config=new ConfigFile(Path.Combine(host,"fixture-ww.cfg"),false);config.SaveOnConfigSet=false;var enabled=config.Bind("Fixture","Smooth",true);Set(guns,"SmoothWeaponSwitch",enabled);
  Set(owner,"nextPackEquipCheck",0f);Call(owner,"InstallWeaponEquipCompatibility");Check((bool)Get(owner,"packEquipInstalled"),"optional bridge discovers WW loaded after initial absence");
  var playerRig=ww.GetType("WildWasteland.Modules.Guns.PlayerRig",true);Set(playerRig,"_cam",view.transform);Set(playerRig,"_arm",arm.transform);Set(playerRig,"_parent",parent.transform);var handler=Make("InactiveNativeHandler");handler.SetActive(false);var fsm=handler.AddComponent<PlayMakerFSM>();fsm.Reset();fsm.enabled=false;fsm.Fsm.Init(fsm);Set(transition,"_handler",fsm);var refs=ww.GetType("WildWasteland.Core.GameRefs",true);Set(refs,"_inPlayFrame",Time.frameCount);Set(refs,"_inPlay",true);
  var flame=FlameFixture(pack,view);var flameRig=(Transform)Get(flame,"HoldingRig");var flameModel=(Transform)Get(flame,"HoldingModel");var flameRunner=flameRig.GetComponent(pack.GetType("ChainsawPrototype.FlamethrowerHoldingRunner",true));Call(owner,"CompleteFlamethrowerPose",flame,flameRunner,false);var flameNodes=flameRig.GetComponentsInChildren<Transform>(true);var flamePositions=new Vector3[flameNodes.Length];var flameRotations=new Quaternion[flameNodes.Length];for(int i=0;i<flameNodes.Length;i++){flamePositions[i]=flameNodes[i].position;flameRotations[i]=flameNodes[i].rotation;}
  var nativePosition=parent.transform.localPosition;var nativeRotation=parent.transform.localRotation;Set(owner,"flameFiring",true);Set(owner,"flameDamagePending",true);
  foreach(float weight in new[]{.25f,.5f,1f,0f}){
   Call(transition,"Restore");Set(transition,"_weight",weight);Call(owner,"ApplyStockPlacement");Call(owner,"CompleteFlamethrowerPose",flame,flameRunner,false);Call(transition,"Pose");
   var turn=parent.transform.rotation*Quaternion.Inverse(arm.transform.rotation*nativeRotation);var origin=arm.transform.TransformPoint(nativePosition);var shift=parent.transform.position-turn*origin;
   Check(Vector3.Distance(model.transform.position,turn*baseModel+shift)<.0001f&&Quaternion.Angle(model.transform.rotation,turn*baseTurn)<.05f,"real WW Pose moves the custom model with weight "+weight);
   bool aligned=true;for(int i=0;i<bones.Length;i++){var node=(Transform)bones.GetValue(i).GetType().GetProperty("Key").GetValue(bones.GetValue(i),null);aligned&=Vector3.Distance(node.position,turn*basePoints[i]+shift)<.0001f;}Check(aligned,"both saved arm grips follow the same transition at weight "+weight);
   var before=model.transform.position;for(int i=0;i<4;i++)Call(owner,"ApplyStockPlacement");Check(Vector3.Distance(before,model.transform.position)<.0001f,"repeated holding/render rebuilds do not compound equip offset at weight "+weight);
   bool flameAligned=true;for(int i=0;i<flameNodes.Length;i++)flameAligned&=Vector3.Distance(flameNodes[i].position,turn*flamePositions[i]+shift)<.0002f&&Quaternion.Angle(flameNodes[i].rotation,turn*flameRotations[i])<.08f;Check(flameAligned,"real WW Pose keeps the flamethrower rig model and both arms rigidly aligned at weight "+weight);
   var flameBefore=flameModel.position;for(int i=0;i<4;i++)Call(owner,"CompleteFlamethrowerPose",flame,flameRunner,false);Check(Vector3.Distance(flameBefore,flameModel.position)<.0001f,"repeated flamethrower holding rebuilds do not compound equip offset at weight "+weight);
  }
  Check((bool)Get(owner,"flameFiring")&&(bool)Get(owner,"flameDamagePending"),"equip-only refresh does not consume pending flame damage or change attack funding");Set(owner,"flameFiring",false);Set(owner,"flameDamagePending",false);
  Call(transition,"Restore");Set(transition,"_weight",.5f);Call(transition,"Pose");var foreign=Make("ForeignView");var state=new object[]{foreign.transform,Quaternion.identity,Vector3.zero};Check(!(bool)Call(owner,"TryPackEquipMotion",state),"a foreign camera cannot inherit an active equip pose");
  var valid=parent.transform.localPosition;parent.transform.localPosition+=Vector3.up*100f;state=new object[]{view.transform,Quaternion.identity,Vector3.zero};Check(!(bool)Call(owner,"TryPackEquipMotion",state),"implausible native pose displacement fails safely");parent.transform.localPosition=valid;
  enabled.Value=false;Call(owner,"ApplyStockPlacement");Check(Vector3.Distance(baseModel,model.transform.position)<.0001f,"disabling WW during an active transition restores the approved base pose");enabled.Value=true;Call(transition,"Restore");Call(owner,"ApplyStockPlacement");Check(Vector3.Distance(baseModel,model.transform.position)<.0001f,"native transition teardown leaves no stale custom offset");
  Check(Vector3.Distance(parent.transform.localPosition,nativePosition)<.0001f&&Quaternion.Angle(parent.transform.localRotation,nativeRotation)<.05f,"compatibility does not overwrite the native parent baseline");
  Call(owner,"CompleteFlamethrowerPose",flame,flameRunner,false);Check(Vector3.Distance(flameModel.position,flamePositions[Array.IndexOf(flameNodes,flameModel)])<.0001f,"flamethrower returns to its approved base after transition teardown");
 }
 object FlameFixture(Assembly pack,GameObject view){
  var itemGo=Make("Flamethrower",Make("HandItemUse",view.transform).transform);var item=itemGo.AddComponent(pack.GetType("ChainsawPrototype.FlamethrowerItem",true));var rig=Make("Flamethrower.HeldRig",view.transform);var model=Make("FlamethrowerModel",rig.transform);Set(item,"HoldingRig",rig.transform);Set(item,"HoldingModel",model.transform);Set(owner,"activeFlame",item);Set(owner,"flamePlayer",view);Call(owner,"ReadFlamethrowerHolding");var placement=Get(owner,"flamePlacement");BuildBones(rig.transform,(Array)Get(placement,"bones"));
  foreach(var pose in (Array)Get(placement,"models")){var go=Make((string)Get(pose,"name"),model.transform);var mesh=new Mesh();mesh.vertices=new[]{Vector3.zero,Vector3.right*.1f,Vector3.up*.1f};mesh.triangles=new[]{0,1,2};mesh.RecalculateBounds();go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>();}
  var runner=rig.AddComponent(pack.GetType("ChainsawPrototype.FlamethrowerHoldingRunner",true));Call(runner,"Configure",owner,item,view.transform);return item;
 }
 object Read(Type type,string path){using(var stream=File.OpenRead(path))return new DataContractJsonSerializer(type).ReadObject(stream);}
 void BuildBones(Transform rig,Array poses){foreach(string side in new[]{"left","right"}){var branch=Make("arm_"+side,rig);var skin=branch.AddComponent<SkinnedMeshRenderer>();var bones=new List<Transform>();foreach(var pose in poses)if((string)Get(pose,"side")==side)bones.Add(Make((string)Get(pose,"name"),branch.transform).transform);skin.bones=bones.ToArray();}}
}
